import hashlib,json
def apply_batch(connection,tenant,request_id,changes,after_plan):
    if not isinstance(tenant,str) or not tenant or not isinstance(request_id,str) or not request_id or not isinstance(changes,list) or not 1<=len(changes)<=20:raise ValueError('bounded tenant request')
    for item in changes:
        if not isinstance(item,dict) or set(item)!={'id','delta'} or not isinstance(item['id'],str) or not item['id'] or type(item['delta']) is not int:raise ValueError('only server-authorized resource id and integer delta')
    ordered=sorted(changes,key=lambda item:item['id'])
    if len({x['id'] for x in ordered})!=len(ordered):raise ValueError('duplicate resource')
    digest=hashlib.sha256(json.dumps(ordered,sort_keys=True,separators=(',',':')).encode()).hexdigest()
    def replay():
        previous=connection.execute('SELECT digest,response FROM requests WHERE tenant=? AND request_id=?',(tenant,request_id)).fetchone()
        if previous:
            if previous[0]!=digest:raise ValueError('request id payload conflict')
            return json.loads(previous[1])
    previous=replay()
    if previous is not None:return previous
    planned={}
    for item in ordered:
        row=connection.execute('SELECT tenant,value FROM resources WHERE id=?',(item['id'],)).fetchone()
        if row is None or row[0]!=tenant:raise PermissionError('batch resource not owned')
        planned[item['id']]=row
    after_plan()
    try:
        connection.execute('BEGIN IMMEDIATE')
        previous=replay()
        if previous is not None:connection.commit();return previous
        results=[]
        for item in ordered:
            row=connection.execute('SELECT tenant,value FROM resources WHERE id=?',(item['id'],)).fetchone()
            if row is None or row[0]!=tenant:raise PermissionError('ownership changed before commit')
            value=row[1]+item['delta']
            if not 0<=value<=100000:raise ValueError('business value out of range')
            results.append({'id':item['id'],'value':value})
        for result in results:connection.execute('UPDATE resources SET value=? WHERE id=?',(result['value'],result['id']))
        response={'request_id':request_id,'results':results}
        connection.execute('INSERT INTO requests VALUES(?,?,?,?)',(tenant,request_id,digest,json.dumps(response,sort_keys=True)))
        connection.commit();return response
    except BaseException:connection.rollback();raise
