from cryptography.hazmat.primitives.ciphers.aead import AESGCM
def prepare_evidence(evidence,key,private_path,shared_path):
    private_path=pathlib.Path(private_path);shared_path=pathlib.Path(shared_path)
    if len(key)!=32 or private_path==shared_path or private_path.exists() or shared_path.exists():raise ValueError('fresh separate paths and 256-bit key')
    raw=json.dumps(evidence,ensure_ascii=False,sort_keys=True,separators=(',',':')).encode()
    events=[]
    for event in evidence['events']:
        if event['error_code'] not in ('TIMEOUT','CONN_REFUSED','OK'):raise ValueError('approved diagnostic error code')
        events.append({name:event[name] for name in ('timestamp','request_id','error_code')})
    process={name:evidence['process'][name] for name in ('pid','state','exe')}
    nonce=os.urandom(12);encrypted=b'OFR1'+nonce+AESGCM(key).encrypt(nonce,raw,b'opsforge-forensics/v1')
    manifest={'transformation_version':1,'event_count':len(events),'original_sha256':hashlib.sha256(raw).hexdigest(),'private_ciphertext_sha256':hashlib.sha256(encrypted).hexdigest(),'already_downloaded_copies_can_be_revoked':False,'on_leak':['withdraw_share','rotate_exposed_credentials']}
    with private_path.open('xb') as stream:os.chmod(private_path,0o600);stream.write(encrypted)
    shared_created=False
    try:
        with shared_path.open('xb') as stream:
            shared_created=True
            os.chmod(shared_path,0o600)
            with zipfile.ZipFile(stream,'w',compression=zipfile.ZIP_DEFLATED) as archive:
                for name,value in [('manifest.json',manifest),('events.json',events),('process.json',process)]:archive.writestr(name,json.dumps(value,ensure_ascii=False,sort_keys=True))
    except BaseException:
        private_path.unlink(missing_ok=True)
        if shared_created:shared_path.unlink(missing_ok=True)
        raise
    return manifest
